// --- reading a Streamable HTTP MCP reply ------------------------------------
// The transport answers `event: message\ndata: {...}` even for a one-shot call,
// so the JSON-RPC envelope has to be lifted out of the SSE frame before
// anything can be read from it.
function unwrap(text) {
  const body = String(text === null || text === undefined ? '' : text);
  for (const line of body.split('\n')) {
    if (line.startsWith('data:')) {
      try { return JSON.parse(line.slice(5).trim()); } catch (e) { return null; }
    }
  }
  try { return JSON.parse(body); } catch (e) { return null; }
}

// Three ways a call comes back without data and only one is an error: a
// transport failure, a tool error (HTTP 200 with `isError` on the envelope),
// and a tool with nothing to say answering in prose despite
// response_format "json". The third throws JSON.parse on a healthy response.
function payloadOf(item) {
  const raw = item && item.json ? (item.json.mcp !== undefined ? item.json.mcp : item.json.data) : '';
  const env = unwrap(raw);
  if (!env) return { error: 'no JSON-RPC envelope came back from the server' };
  if (env.error) return { error: String((env.error && env.error.message) || 'JSON-RPC error') };
  const result = env.result || {};
  const text = String((((result.content || [])[0]) || {}).text || '');
  if (result.isError) return { error: text.slice(0, 300) };
  // Python's json.dumps writes a bare NaN for a missing float and neither NaN
  // nor Infinity is valid JSON, so a payload that is otherwise perfect throws
  // on parse. Only value positions are rewritten, so a string reading "NaN" is
  // left alone.
  try {
    return { data: JSON.parse(String(text).replace(/:\s*(-?Infinity|NaN)(\s*[,}\]])/g, ': null$2')) };
  } catch (e) {
    return { note: text.slice(0, 300) };
  }
}

// The endpoint answering at all is not proof it is an MCP server, and an MCP
// server answering is not proof it is this one. tools/list is the cheapest call
// in the protocol, so a wrong URL surfaces here rather than as an empty report
// six nodes later.
const url = $('Settings').first().json.mcp_url;
const NEEDED = ['get_recent_filings'];

const env = unwrap($json.mcp !== undefined ? $json.mcp : $json.data);
const tools = env && env.result && Array.isArray(env.result.tools) ? env.result.tools : null;

if (!tools) {
  throw new Error(
    'No tool list came back from ' + url + '. A Streamable HTTP MCP server ' +
    'answers POST on /mcp: a 404 usually means the path is missing /mcp, and a ' +
    '421 means the server is up but your Host header is not on its allow-list ' +
    '(start it with --allowed-host). From n8n in Docker the host machine is ' +
    'host.docker.internal, not localhost.'
  );
}

const have = new Set(tools.map((t) => String(t.name)));
const missing = NEEDED.filter((t) => !have.has(t));
if (missing.length) {
  throw new Error(
    'The server at ' + url + ' is missing ' + missing.join(', ') + '. It offers ' +
    tools.length + ' tool(s), so it is an MCP server - just not this one. ' +
    'Expected edgar-mcp 1.1.0 or later.'
  );
}

return [{ json: { mcp_url: url, tools_offered: tools.length } }];

// One item per company, so the filing lookup below runs once each and the
// fetches downstream stay one company per item all the way to the diff.
const cfg = $('Settings').first().json;

const tickers = String(cfg.tickers || '')
  .split(',')
  .map((t) => t.trim().toUpperCase())
  // Letters, digits, dot and dash. Anything else is a typo, and it would be
  // interpolated straight into the JSON-RPC body below.
  .filter((t) => /^[A-Z0-9.\-]{1,10}$/.test(t))
  .slice(0, Math.max(1, Number(cfg.max_companies) || 5));

if (!tickers.length) {
  throw new Error(
    'No usable tickers in Settings. Expected a comma separated list like ' +
    '"AAPL, MSFT, NVDA".'
  );
}

// Deduplicated, because the Data Table is keyed on the ticker and the same
// symbol listed twice would race itself on the upsert.
return [...new Set(tickers)].map((ticker) => ({ json: { ticker } }));

