// Pair each company with the two most recent annual reports and decide, here,
// whether there is anything to do. Everything below this node assumes both
// URLs exist and that the newer one has not been reported before.
const cfg = $('Settings').first().json;
const form = String(cfg.form_type || '10-K');
const asked = $('Pick The Companies').all().map((i) => i.json.ticker);
const items = $input.all();

// The accession number, not the filing date. A 10-K stays the newest filing for
// a year, so a weekly schedule checking dates would re-report the same document
// fifty-one times.
const seen = new Map(
  $('Read What We Reported').all()
    .filter((i) => i.json && i.json.ticker)
    .map((i) => [String(i.json.ticker).toUpperCase(), String(i.json.accession || '')])
);

return asked.map((ticker, i) => {
  const got = payloadOf(items[i]);

  if (got.error) {
    return { json: { ticker, usable: false, reason: 'EDGAR call failed: ' + got.error } };
  }
  if (got.note) {
    // The tool answered in prose on a successful call, which is what it does
    // for a ticker it cannot resolve. Left unhandled this parses to nothing and
    // the company silently disappears from the report.
    return { json: { ticker, usable: false, reason: got.note } };
  }

  const d = got.data || {};
  const filings = Array.isArray(d.filings) ? d.filings : [];
  if (filings.length < 2) {
    return {
      json: {
        ticker,
        company: d.company || ticker,
        usable: false,
        reason:
          'EDGAR has ' + filings.length + ' ' + form + ' filing(s) for this company. ' +
          'Two are needed to compare, so a first-time filer has nothing to diff yet.',
      },
    };
  }

  const [current, previous] = filings;
  const already = seen.get(ticker) === String(current.accession);

  return {
    json: {
      ticker,
      company: d.company || ticker,
      cik: d.cik || null,
      form,
      usable: !already,
      reason: already
        ? 'Already reported ' + current.accession + '. Nothing new has been filed.'
        : '',
      accession: current.accession,
      filed_on: current.filingDate,
      period: current.reportDate,
      current_url: current.url,
      previous_accession: previous.accession,
      previous_filed_on: previous.filingDate,
      previous_url: previous.url,
    },
  };
});

// --- turning filing HTML into comparable paragraphs -------------------------
// A 10-K is 1.5 MB of nested tables and inline styles. There is no DOM in the
// Code node sandbox - no URL, no fetch, no DOMParser - so the tags come out by
// regex, closing block tags become newlines so paragraphs survive, and the
// entities EDGAR actually emits are mapped by hand.
function toText(html) {
  return String(html || '')
    .replace(/<(script|style)[\s\S]*?<\/\1>/gi, ' ')
    .replace(/<\/(p|div|tr|li|h\d|table)>/gi, '\n')
    .replace(/<br\s*\/?>/gi, '\n')
    .replace(/<[^>]+>/g, ' ')
    .replace(/&nbsp;|&#160;/gi, ' ')
    .replace(/&#8217;|&rsquo;|&#39;|&apos;/gi, "'")
    .replace(/&#8220;|&#8221;|&ldquo;|&rdquo;|&quot;/gi, '"')
    .replace(/&#8212;|&mdash;|&#8211;|&ndash;/gi, '-')
    .replace(/&lt;/gi, '<')
    .replace(/&gt;/gi, '>')
    .replace(/&amp;/gi, '&')
    .replace(/[ \t ]+/g, ' ')
    .replace(/\n\s*\n\s*\n+/g, '\n\n');
}

// "Item 1A. Risk Factors" appears at least twice in every filing - once in the
// table of contents and once as the heading of the section itself - and the
// contents entry is followed immediately by the next contents line. Taking the
// first match returns one line of text. The real section is the longest run
// between a start match and the next top-level item heading after it.
function riskSection(text) {
  // matchAll rather than a while loop over the RegExp exec method: the template
  // submission endpoint's firewall drops any POST whose body quotes that call,
  // and the upload fails as "Failed to fetch" with nothing else said.
  const starts = [...text.matchAll(/item\s*1a\.?\s*[-–—:]?\s*risk\s*factors/gi)].map((m) => m.index);
  if (!starts.length) return null;
  const ends = [...text.matchAll(/item\s*1b\.?\s*[-–—:]?\s*unresolved|item\s*2\.?\s*[-–—:]?\s*propert/gi)].map((m) => m.index);

  let best = null;
  for (const start of starts) {
    const end = ends.find((e) => e > start);
    // A filing that never says "Item 1B" or "Item 2" again is malformed, but
    // capping the run keeps a bad parse from swallowing the whole document.
    const stop = end === undefined ? Math.min(text.length, start + 400000) : end;
    if (stop > start && (!best || stop - start > best.length)) {
      best = { start: start, stop: stop, length: stop - start };
    }
  }
  return best ? text.slice(best.start, best.stop) : null;
}

// 200 characters is the floor that separates a risk factor from a page number,
// a running header or a one-line sub-heading. Below it the section is mostly
// navigation furniture and the diff fills with noise.
function paragraphs(section, minChars) {
  return String(section || '')
    .split(/\n+/)
    .map((s) => s.trim())
    .filter((s) => s.length >= minChars);
}

function normalise(s) {
  return String(s).toLowerCase().replace(/[^a-z0-9 ]+/g, ' ').replace(/\s+/g, ' ').trim();
}

// Words of four letters or more, as a set. Short words are the ones every
// paragraph shares - "the", "and", "of", "may" - so counting them pulls every
// pair towards the middle and flattens the bands the classification depends on.
function tokens(s) {
  return new Set(normalise(s).split(' ').filter((w) => w.length > 3));
}

// Jaccard rather than a character diff: risk factors get reordered clauses and
// swapped synonyms, and a character diff scores those as barely related while a
// reader would call them the same paragraph.
function overlap(a, b) {
  let shared = 0;
  for (const t of a) if (b.has(t)) shared += 1;
  const union = a.size + b.size - shared;
  return union ? shared / union : 0;
}

// Runs immediately after the fetch so the 1.5 MB of HTML dies here. Everything
// downstream carries the risk factors alone, which for Apple is 68 KB rather
// than 1.5 MB - and there are two of these per company.
const cfg = $('Settings').first().json;
const minChars = Math.max(80, Number(cfg.min_paragraph_chars) || 200);
// Read from the list node and re-apply the same test, rather than reading the
// IF by name: an IF has two outputs and a by-name read returns one of them,
// with nothing on the canvas saying which. This is the same set the true branch
// carries, in the same order.
const meta = $('Read The Filing List').all().map((i) => i.json).filter((r) => r.usable);
const items = $input.all();

return items.map((item, i) => {
  const row = meta[i] || {};
  const status = Number(item.json.status || 0);
  const html = item.json.data !== undefined ? item.json.data : item.json.body;

  // neverError is on, so a 403 arrives as a green node holding an error page.
  // The SEC answers a client with no descriptive User-Agent exactly that way.
  if (status >= 400 || !html) {
    return {
      json: Object.assign({}, row, {
        parsed: false,
        reason:
          'SEC returned HTTP ' + (status || 'no body') + ' for the ' + row.filed_on +
          ' filing. The SEC requires a descriptive User-Agent with contact ' +
          'details on every request - check sec_user_agent in Settings.',
      }),
    };
  }

  const section = riskSection(toText(html));
  if (!section) {
    return {
      json: Object.assign({}, row, {
        parsed: false,
        reason:
          'No "Item 1A. Risk Factors" heading in the ' + row.filed_on + ' filing. ' +
          'Smaller reporting companies are allowed to omit the section entirely.',
      }),
    };
  }

  return {
    json: Object.assign({}, row, {
      parsed: true,
      current_paragraphs: paragraphs(section, minChars),
      current_section_chars: section.length,
    }),
  };
});

