// The whole point of the template, and it runs before any model is involved.
//
// Hashing paragraphs and taking a set difference was the first attempt and it
// reported all 81 of Apple's 2025 risk factors as new: a carried-over risk
// factor is almost never byte-identical, because a date moves or a product gets
// named. So each paragraph is matched to its best unused counterpart by token
// overlap and the score decides which of four things happened to it.
const cfg = $('Settings').first().json;
const SAME = 0.95;      // above this, the paragraph is last year's text
const REWORDED = 0.80;  // between the two, a light edit worth counting only
const PAIRED = 0.55;    // below this there is no counterpart at all
const maxForModel = Math.max(5, Number(cfg.max_changes_to_read) || 25);
const quoteChars = Math.max(200, Number(cfg.quote_chars) || 700);

return $input.all().map((item) => {
  const row = item.json;
  if (!row.parsed) return { json: Object.assign({}, row, { changes: 0 }) };

  const now = row.current_paragraphs || [];
  const prev = row.previous_paragraphs || [];
  const nowTokens = now.map(tokens);
  const prevTokens = prev.map(tokens);

  // Greedy one-to-one. A paragraph already claimed cannot be claimed again,
  // otherwise one generic risk factor absorbs several of this year's and the
  // removals vanish.
  const claimed = new Set();
  const added = [];
  const rewritten = [];
  let reworded = 0;
  let unchanged = 0;

  now.forEach((text, i) => {
    let bestIndex = -1;
    let bestScore = 0;
    prevTokens.forEach((candidate, j) => {
      if (claimed.has(j)) return;
      const score = overlap(nowTokens[i], candidate);
      if (score > bestScore) {
        bestScore = score;
        bestIndex = j;
      }
    });

    if (bestIndex >= 0 && bestScore >= PAIRED) claimed.add(bestIndex);

    if (bestScore >= SAME) unchanged += 1;
    else if (bestScore >= REWORDED) reworded += 1;
    else if (bestScore >= PAIRED) {
      rewritten.push({ similarity: Math.round(bestScore * 100) / 100, now: text, was: prev[bestIndex] });
    } else added.push(text);
  });

  const removed = prev.filter((_, j) => !claimed.has(j));

  // Additions first, then removals, then the rewrites: a risk the company has
  // started disclosing outranks one it has reworded. The cap is on what the
  // model reads, and what it cost is reported rather than swallowed.
  const material = []
    .concat(added.map((t) => ({ kind: 'added', text: t })))
    .concat(removed.map((t) => ({ kind: 'removed', text: t })))
    .concat(rewritten.map((r) => ({ kind: 'rewritten', similarity: r.similarity, text: r.now, was: r.was })));

  const forModel = material.slice(0, maxForModel).map((c) => ({
    kind: c.kind,
    similarity: c.similarity,
    text: String(c.text).slice(0, quoteChars),
    was: c.was ? String(c.was).slice(0, quoteChars) : undefined,
  }));

  return {
    json: Object.assign({}, row, {
      // The arrays themselves are dropped here. They are two copies of a 68 KB
      // section and nothing below this node reads them.
      current_paragraphs: undefined,
      previous_paragraphs: undefined,
      counts: {
        this_year: now.length,
        last_year: prev.length,
        added: added.length,
        removed: removed.length,
        rewritten: rewritten.length,
        reworded: reworded,
        unchanged: unchanged,
      },
      changes: added.length + removed.length + rewritten.length,
      sent_to_model: forModel.length,
      not_sent: Math.max(0, material.length - forModel.length),
      material: forModel,
    }),
  };
});

