// One document for the whole watchlist rather than one per company, so the
// Docs nodes below run once. The IF above has already narrowed this branch to
// the companies that changed, and the full picture is read back by name.
const cfg = $('Settings').first().json;
const rows = $('Diff The Risk Factors').all().map((i) => i.json).filter((r) => r.changes > 0);
const readings = $input.all().map((i) => String((i.json && i.json.text) || '').trim());

// The Docs insert writes the string it is given - markdown is not parsed, so
// "## Heading" would arrive on the page as those characters. Headings are made
// of capitals and blank lines instead.
const lines = [];
lines.push('RISK FACTOR CHANGES');
lines.push(new Date().toISOString().slice(0, 10));
lines.push('');
lines.push(
  rows.length + ' of ' + $('Diff The Risk Factors').all().length +
  ' companies filed a new annual report with changed risk factors.'
);
lines.push('');

rows.forEach((r, i) => {
  const c = r.counts || {};
  lines.push('');
  lines.push('----------------------------------------');
  lines.push((r.company || r.ticker).toUpperCase() + '  (' + r.ticker + ')');
  lines.push('Filed ' + r.filed_on + ' for the period ending ' + r.period);
  lines.push('Compared against the ' + r.previous_filed_on + ' filing');
  lines.push('Accession ' + r.accession);
  lines.push('');
  lines.push(
    c.added + ' new, ' + c.removed + ' dropped, ' + c.rewritten + ' rewritten, ' +
    c.reworded + ' lightly reworded, ' + c.unchanged + ' unchanged  ' +
    '(' + c.last_year + ' paragraphs last year, ' + c.this_year + ' this year)'
  );
  // Never silently. A capped read that reports itself as complete is worse than
  // one that says what it left out.
  if (r.not_sent > 0) {
    lines.push(
      'The summary below covers ' + r.sent_to_model + ' of ' + (r.sent_to_model + r.not_sent) +
      ' changed paragraphs. Raise max_changes_to_read in Settings to widen it.'
    );
  }
  lines.push('');
  lines.push(readings[i] || '(no summary was returned for this company)');
  lines.push('');
  lines.push('Read the filing: ' + r.current_url);
});

return [{
  json: {
    title: 'Risk factor changes - ' + new Date().toISOString().slice(0, 10),
    folder: cfg.docs_folder || 'root',
    report: lines.join('\n'),
    companies: rows.length,
  },
}];
